/**
 * DispatchStreamConsumer — owns the dispatch Redis Stream.
 *
 * Consumes jobs from the dispatch stream via XREADGROUP (consumer group),
 * redelivers stuck entries via XAUTOCLAIM, and routes jobs to the DLQ
 * after maxDeliveries failed attempts.
 *
 * Per-handle idempotency:
 *   Before docker run, acquires: SET dispatch:lock:<handle> <owner> NX PX <ttl>
 *   Only the lock winner spawns; losers skip + XACK to remove from their PEL.
 *   The platform.handle=<handle> label check is a cheap post-spawn backstop.
 *
 * DLQ handling:
 *   After maxDeliveries, the entry is moved to DISPATCH_DLQ_KEY and a
 *   synthetic "failed" completion is posted to the broker /callback, routing
 *   the terminal failure through the normal completion path.
 *
 * Global spawn cap:
 *   Before spawning, reads broker GET /registry-size and skips if at cap.
 *   On cap-exceeded, the entry is left pending (XREADGROUP will redeliver).
 */

import * as http from "node:http";
import * as https from "node:https";
import { randomUUID } from "node:crypto";
import type { RedisClientType } from "redis";
import {
  DISPATCH_STREAM_KEY,
  DISPATCH_CONSUMER_GROUP,
  DISPATCH_DLQ_KEY,
  type DispatchJob,
} from "@workflow/runtime-abi";
import type { DockerSpawner } from "./spawner.js";
import type { CredentialAdapter } from "./credential.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ConsumerOpts {
  redis: RedisClientType;
  spawner: DockerSpawner;
  credential: CredentialAdapter;
  brokerUrl: string;
  consumerId: string;
  maxConcurrent: number;
  maxDeliveries: number;
  spawnLockTtlMs: number;
  pollBlockMs: number;
  xautoclaimMinIdleMs: number;
  batchSize: number;
}

interface StreamEntry {
  id: string;
  message: Record<string, string>;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

function httpPost(url: string, body: string): Promise<void> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try {
      u = new URL(url);
    } catch {
      reject(new Error(`httpPost: invalid URL: ${url}`));
      return;
    }
    const lib = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname + u.search,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
        },
      },
      (res) => { res.resume(); resolve(); },
    );
    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

function httpGet(url: string): Promise<string> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try {
      u = new URL(url);
    } catch {
      reject(new Error(`httpGet: invalid URL: ${url}`));
      return;
    }
    const lib = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname + u.search,
        method: "GET",
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () => resolve(Buffer.concat(chunks).toString()));
        res.on("error", reject);
      },
    );
    req.on("error", reject);
    req.end();
  });
}

// ── Consumer ──────────────────────────────────────────────────────────────────

export class DispatchStreamConsumer {
  private readonly redis: RedisClientType;
  private readonly spawner: DockerSpawner;
  private readonly credential: CredentialAdapter;
  private readonly brokerUrl: string;
  private readonly consumerId: string;
  private readonly maxConcurrent: number;
  private readonly maxDeliveries: number;
  private readonly spawnLockTtlMs: number;
  private readonly pollBlockMs: number;
  private readonly xautoclaimMinIdleMs: number;
  private readonly batchSize: number;

  private stopped = false;

  constructor(opts: ConsumerOpts) {
    this.redis = opts.redis;
    this.spawner = opts.spawner;
    this.credential = opts.credential;
    this.brokerUrl = opts.brokerUrl;
    this.consumerId = opts.consumerId;
    this.maxConcurrent = opts.maxConcurrent;
    this.maxDeliveries = opts.maxDeliveries;
    this.spawnLockTtlMs = opts.spawnLockTtlMs;
    this.pollBlockMs = opts.pollBlockMs;
    this.xautoclaimMinIdleMs = opts.xautoclaimMinIdleMs;
    this.batchSize = opts.batchSize;
  }

  /**
   * Ensure the consumer group exists on the dispatch stream.
   * Creates the stream + group if absent ($ = only new messages).
   */
  async ensureConsumerGroup(): Promise<void> {
    try {
      await this.redis.xGroupCreate(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, "$", {
        MKSTREAM: true,
      });
      emit({ type: "consumer_group_created", group: DISPATCH_CONSUMER_GROUP });
    } catch (err) {
      // BUSYGROUP: group already exists — ignore.
      if (String(err).includes("BUSYGROUP")) return;
      throw err;
    }
  }

  stop(): void {
    this.stopped = true;
  }

  /**
   * Run the main dispatch loop until stop() is called.
   *
   * Each iteration:
   *   1. XAUTOCLAIM stuck pending entries.
   *   2. XREADGROUP for new entries.
   *   3. Process all collected entries.
   */
  async run(): Promise<void> {
    await this.ensureConsumerGroup();

    while (!this.stopped) {
      try {
        // 1. Reclaim stuck entries (pending longer than xautoclaimMinIdleMs).
        const reclaimed = await this._xautoclaim();

        // 2. Read new entries (blocks up to pollBlockMs if none pending).
        const fresh = await this._xreadgroup();

        const entries = [...reclaimed, ...fresh];
        if (entries.length > 0) {
          await Promise.all(entries.map((e) => this._processEntry(e)));
        }
      } catch (err) {
        emit({ type: "consumer_loop_error", error: String(err) });
        // Brief back-off to avoid a tight error loop.
        await new Promise((r) => setTimeout(r, 1_000));
      }
    }
  }

  // ── Internal ───────────────────────────────────────────────────────────────

  private async _xautoclaim(): Promise<StreamEntry[]> {
    try {
      const result = await (this.redis as any).xAutoClaim(
        DISPATCH_STREAM_KEY,
        DISPATCH_CONSUMER_GROUP,
        this.consumerId,
        this.xautoclaimMinIdleMs,
        "0-0",
        { COUNT: this.batchSize },
      );
      // node-redis v4+ returns { nextId, messages }
      const messages: Array<{ id: string; message: Record<string, string> }> =
        result?.messages ?? [];
      return messages.map((m) => ({ id: m.id, message: m.message }));
    } catch (err) {
      // XAUTOCLAIM fails if the stream doesn't exist yet.
      if (String(err).includes("ERR no such key")) return [];
      emit({ type: "xautoclaim_error", error: String(err) });
      return [];
    }
  }

  private async _xreadgroup(): Promise<StreamEntry[]> {
    try {
      const results = await this.redis.xReadGroup(
        DISPATCH_CONSUMER_GROUP,
        this.consumerId,
        [{ key: DISPATCH_STREAM_KEY, id: ">" }],
        { COUNT: this.batchSize, BLOCK: this.pollBlockMs },
      );
      if (!results || results.length === 0) return [];
      const entries: StreamEntry[] = [];
      for (const stream of results) {
        for (const msg of stream.messages) {
          entries.push({ id: msg.id, message: msg.message as Record<string, string> });
        }
      }
      return entries;
    } catch (err) {
      emit({ type: "xreadgroup_error", error: String(err) });
      return [];
    }
  }

  /**
   * Get the delivery count for a pending entry.
   * Returns 1 if XPENDING-RANGE is unavailable (treat as first delivery).
   */
  async _getDeliveryCount(entryId: string): Promise<number> {
    try {
      const pending = await this.redis.xPendingRange(
        DISPATCH_STREAM_KEY,
        DISPATCH_CONSUMER_GROUP,
        entryId,
        entryId,
        1,
      );
      if (pending.length === 0) return 1;
      // node-redis v4+ uses `deliveriesCounter` for the delivery count field.
      const entry = pending[0] as { deliveriesCounter?: number; deliveryCount?: number };
      return entry.deliveriesCounter ?? entry.deliveryCount ?? 1;
    } catch {
      return 1;
    }
  }

  private async _processEntry(entry: StreamEntry): Promise<void> {
    const { id, message } = entry;

    // Parse DispatchJob from the stream entry.
    let job: DispatchJob;
    try {
      const raw = message.job;
      if (!raw) throw new Error("missing 'job' field in stream entry");
      job = JSON.parse(raw) as DispatchJob;
    } catch (err) {
      emit({ type: "dispatch_parse_error", entry_id: id, error: String(err) });
      // Malformed entry: ACK to discard it rather than looping forever.
      await this._xack(id);
      return;
    }

    // Check delivery count against maxDeliveries.
    const deliveryCount = await this._getDeliveryCount(id);
    if (deliveryCount > this.maxDeliveries) {
      emit({
        type: "dispatch_dlq",
        handle: job.handle,
        entry_id: id,
        delivery_count: deliveryCount,
        max_deliveries: this.maxDeliveries,
      });
      await this._moveToDlq(id, job);
      return;
    }

    // Check global spawn cap via broker registry-size.
    const registrySize = await this._getRegistrySize();
    if (registrySize >= this.maxConcurrent) {
      emit({
        type: "dispatch_cap_exceeded",
        handle: job.handle,
        registry_size: registrySize,
        max_concurrent: this.maxConcurrent,
      });
      // Leave in PEL; XAUTOCLAIM will redeliver when capacity frees up.
      return;
    }

    // Acquire per-handle spawn lock before docker run (closes TOCTOU window).
    const lockOwner = randomUUID();
    const lockKey = `dispatch:lock:${job.handle}`;
    const lockAcquired = await this._acquireSpawnLock(lockKey, lockOwner);
    if (!lockAcquired) {
      emit({
        type: "dispatch_lock_lost",
        handle: job.handle,
        entry_id: id,
      });
      // Another dispatcher won; XACK to remove from our PEL.
      await this._xack(id);
      return;
    }

    // Post-spawn backstop: check if a container already exists for this handle.
    const existingId = await this.spawner.findExistingContainer(job.handle);
    if (existingId !== null) {
      emit({
        type: "dispatch_duplicate_container",
        handle: job.handle,
        container_id: existingId,
        entry_id: id,
      });
      await this._releaseSpawnLock(lockKey, lockOwner);
      await this._xack(id);
      return;
    }

    // Resolve credentials — dispatcher is the sole credential holder.
    let githubToken: string;
    let sshPrivateKey: string;
    try {
      [githubToken, sshPrivateKey] = await Promise.all([
        this.credential.getGitHubToken(),
        this.credential.getSshPrivateKey(),
      ]);
    } catch (err) {
      emit({ type: "dispatch_credential_error", handle: job.handle, error: String(err) });
      await this._releaseSpawnLock(lockKey, lockOwner);
      return; // Leave in PEL for redelivery.
    }

    // Spawn the executor container.
    try {
      const { containerId } = await this.spawner.spawn(job, githubToken, sshPrivateKey);
      emit({
        type: "dispatch_spawn_ok",
        handle: job.handle,
        task_id: job.task_id,
        feature_id: job.feature_id,
        container_id: containerId,
        entry_id: id,
      });
      // XACK after successful spawn.
      await this._xack(id);
    } catch (err) {
      emit({
        type: "dispatch_spawn_error",
        handle: job.handle,
        task_id: job.task_id,
        error: String(err),
        entry_id: id,
      });
      // Release lock so another instance can retry.
      await this._releaseSpawnLock(lockKey, lockOwner);
      // Leave in PEL; XAUTOCLAIM will redeliver.
    }
    // Lock is intentionally kept until container starts (not released on success):
    // the container label becomes the post-spawn guard; the lock prevents
    // the TOCTOU window during the spawning gap.
  }

  private async _xack(entryId: string): Promise<void> {
    try {
      await this.redis.xAck(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, entryId);
    } catch (err) {
      emit({ type: "xack_error", entry_id: entryId, error: String(err) });
    }
  }

  /**
   * Move a job to the DLQ and post a synthetic failed completion to the broker.
   * The orchestrator learns about the terminal failure through the normal
   * completion path — no dispatched-vs-not bookkeeping at the orchestrator.
   */
  private async _moveToDlq(entryId: string, job: DispatchJob): Promise<void> {
    try {
      await this.redis.xAdd(DISPATCH_DLQ_KEY, "*", { job: JSON.stringify(job) });
    } catch (err) {
      emit({ type: "dlq_write_error", handle: job.handle, error: String(err) });
    }

    // Post synthetic failed completion so the orchestrator learns through /callback.
    const callbackBody = JSON.stringify({
      handle: job.handle,
      nonce: job.nonce,
      result: {
        terminal_status: "failed",
        blocked_reason: `dispatch_dlq_after_${this.maxDeliveries}_deliveries`,
      },
    });

    try {
      await httpPost(`${job.callback_url}`, callbackBody);
      emit({
        type: "dispatch_dlq_callback_posted",
        handle: job.handle,
        callback_url: job.callback_url,
      });
    } catch (err) {
      emit({
        type: "dispatch_dlq_callback_error",
        handle: job.handle,
        error: String(err),
      });
    }

    // XACK after routing to DLQ.
    await this._xack(entryId);
  }

  /**
   * Read the current in-flight count from the broker GET /registry-size.
   * Returns maxConcurrent on error so we conservatively skip spawning.
   */
  async _getRegistrySize(): Promise<number> {
    try {
      const body = await httpGet(`${this.brokerUrl}/registry-size`);
      const parsed = JSON.parse(body) as { size?: number };
      return typeof parsed.size === "number" ? parsed.size : this.maxConcurrent;
    } catch {
      return this.maxConcurrent;
    }
  }

  /**
   * Acquire a per-handle spawn lock using SET NX PX.
   * Returns true if the lock was acquired.
   */
  async _acquireSpawnLock(lockKey: string, lockOwner: string): Promise<boolean> {
    const result = await this.redis.set(lockKey, lockOwner, {
      NX: true,
      PX: this.spawnLockTtlMs,
    });
    return result === "OK";
  }

  /**
   * Release the spawn lock only if we still own it (check-and-delete via GET).
   * Best-effort: if the key expired, nothing to do.
   */
  async _releaseSpawnLock(lockKey: string, lockOwner: string): Promise<void> {
    try {
      const current = await this.redis.get(lockKey);
      if (current === lockOwner) {
        await this.redis.del(lockKey);
      }
    } catch {
      // Best-effort.
    }
  }
}

