1	/**
2	 * Unit tests for DispatchStreamConsumer.
3	 *
4	 * All Redis and spawner interactions are faked — no real Redis or Docker required.
5	 *
6	 * Scenarios:
7	 *   1. Happy path: job consumed, container spawned, XACK'd.
8	 *   2. Spawn lock: exactly one winner spawns when two dispatchers race.
9	 *   3. DLQ routing: job moved to DLQ + synthetic /callback after maxDeliveries.
10	 *   4. Cap enforcement: spawn skipped when registry-size >= maxConcurrent.
11	 *   5. XAUTOCLAIM redelivery: stuck entries are reclaimed and processed.
12	 *   6. Duplicate container: label-backstop check prevents second spawn.
13	 *   7. Malformed entry: ACK'd and discarded without crashing.
14	 */
15	
16	import { describe, it, expect, beforeEach, vi } from "vitest";
17	import { randomUUID } from "node:crypto";
18	import { DispatchStreamConsumer, type ConsumerOpts } from "../src/consumer.js";
19	import type { DispatchJob } from "@workflow/runtime-abi";
20	import { DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, DISPATCH_DLQ_KEY } from "@workflow/runtime-abi";
21	import type { DockerSpawner } from "../src/spawner.js";
22	import type { CredentialAdapter } from "../src/credential.js";
23	
24	// ── Fake implementations ──────────────────────────────────────────────────────
25	
26	function makeJob(overrides?: Partial<DispatchJob>): DispatchJob {
27	  return {
28	    handle: randomUUID(),
29	    nonce: randomUUID(),
30	    kind: "impl",
31	    task_id: "T4",
32	    feature_id: "standalone-executor-hardening",
33	    workspace_id: "ws-test",
34	    task_repo_url: "git@github.com:org/repo.git",
35	    task_repo_branch: "feature/test-T4",
36	    task_base_branch: "feature/standalone-executor-hardening",
37	    task_repo_base_branch: "main",
38	    mgmt_repo_url: "git@github.com:org/workspace.git",
39	    executor_workdir: "/workspace",
40	    callback_url: "http://broker:7000/callback",
41	    enqueued_at: new Date().toISOString(),
