46	function makeEntry(job: DispatchJob, id?: string): { id: string; message: Record<string, string> } {
47	  return { id: id ?? `${Date.now()}-0`, message: { job: JSON.stringify(job) } };
48	}
49	
50	interface FakeRedis {
51	  // Collected calls for assertion
52	  xAddCalls: Array<{ key: string; id: string; fields: Record<string, string> }>;
53	  xAckCalls: Array<{ key: string; group: string; id: string }>;
54	  xPendingRangeResults: Map<string, { deliveryCount: number }[]>;
55	  setCalls: Array<{ key: string; value: string; opts: { NX?: boolean; PX?: number } }>;
56	  setResults: Map<string, string | null>;
57	  getCalls: string[];
58	  getResults: Map<string, string | null>;
59	  delCalls: string[];
60	
61	  // Behaviour overrides
62	  xAdd: ReturnType<typeof vi.fn>;
63	  xAck: ReturnType<typeof vi.fn>;
64	  xPendingRange: ReturnType<typeof vi.fn>;
65	  set: ReturnType<typeof vi.fn>;
66	  get: ReturnType<typeof vi.fn>;
67	  del: ReturnType<typeof vi.fn>;
68	  xGroupCreate: ReturnType<typeof vi.fn>;
69	  xReadGroup: ReturnType<typeof vi.fn>;
70	  xAutoClaim: ReturnType<typeof vi.fn>;
71	}
72	
73	function makeFakeRedis(opts?: {
74	  pendingByEntryId?: Map<string, number>;
75	  setResultFn?: (key: string) => string | null;
76	}): FakeRedis {
77	  const xAddCalls: FakeRedis["xAddCalls"] = [];
78	  const xAckCalls: FakeRedis["xAckCalls"] = [];
79	  const setCalls: FakeRedis["setCalls"] = [];
80	  const getCalls: string[] = [];
81	  const delCalls: string[] = [];
82	
83	  const r: FakeRedis = {
84	    xAddCalls,
85	    xAckCalls,
86	    xPendingRangeResults: new Map(),
87	    setCalls,
88	    setResults: new Map(),
89	    getCalls,
90	    getResults: new Map(),
91	    delCalls,
92	
93	    xAdd: vi.fn(async (key: string, id: string, fields: Record<string, string>) => {
94	      xAddCalls.push({ key, id, fields });
95	      return "1-0";
96	    }),
97	    xAck: vi.fn(async (key: string, group: string, id: string) => {
98	      xAckCalls.push({ key, group, id });
99	      return 1;
100	    }),
101	    xPendingRange: vi.fn(async (key: string, group: string, start: string, end: string, count: number) => {
102	      const entryId = start; // our call uses same start=end=entryId
103	      const deliveryCount = opts?.pendingByEntryId?.get(entryId) ?? 1;
104	      return [{ id: entryId, deliveryCount, consumer: "test", idle: 100 }];
105	    }),
106	    set: vi.fn(async (key: string, value: string, setOpts: { NX?: boolean; PX?: number }) => {
107	      setCalls.push({ key, value, opts: setOpts });
108	      if (opts?.setResultFn) return opts.setResultFn(key);
109	      // Default: always grant the lock (return "OK")
110	      return "OK";
111	    }),
112	    get: vi.fn(async (key: string) => {
113	      getCalls.push(key);
114	      return null;
115	    }),
116	    del: vi.fn(async (key: string) => {
117	      delCalls.push(key);
118	      return 1;
119	    }),
120	    xGroupCreate: vi.fn(async () => "OK"),
121	    xReadGroup: vi.fn(async () => []),
122	    xAutoClaim: vi.fn(async () => ({ nextId: "0-0", messages: [] })),
123	  };
124	  return r;
125	}
126	
127	function makeFakeSpawner(opts?: {
128	  existingHandle?: string;
129	  spawnError?: Error;
130	}): DockerSpawner & { spawnCalls: DispatchJob[] } {
131	  const spawnCalls: DispatchJob[] = [];
132	  return {
133	    spawnCalls,
134	    findExistingContainer: vi.fn(async (handle: string) => {
135	      return opts?.existingHandle === handle ? "fake-container-id" : null;
136	    }),
137	    spawn: vi.fn(async (job: DispatchJob) => {
138	      if (opts?.spawnError) throw opts.spawnError;
139	      spawnCalls.push(job);
140	      return { containerId: `container-${job.handle}` };
141	    }),
142	  } as unknown as DockerSpawner & { spawnCalls: DispatchJob[] };
143	}
144	
145	function makeFakeCredential(): CredentialAdapter {
146	  return {
147	    getGitHubToken: vi.fn(async () => "fake-token"),
148	    getSshPrivateKey: vi.fn(async () => "fake-key"),
149	  };
150	}
