152	const BASE_OPTS = {
153	  brokerUrl: "http://broker:7000",
154	  consumerId: "test-dispatcher",
155	  maxConcurrent: 5,
156	  maxDeliveries: 3,
157	  spawnLockTtlMs: 300_000,
158	  pollBlockMs: 100,
159	  xautoclaimMinIdleMs: 30_000,
160	  batchSize: 10,
161	};
