163	// ── Tests ─────────────────────────────────────────────────────────────────────
164	
165	describe("DispatchStreamConsumer", () => {
166	
167	  describe("_processEntry — happy path", () => {
168	    it("spawns container, then XACKs on success", async () => {
169	      const redis = makeFakeRedis();
170	      const spawner = makeFakeSpawner();
171	      const credential = makeFakeCredential();
